pub fn read_scenereference(value: &Bound<'_, PyAny>) -> PyResult<zipzi_core::SceneReference> {
    match value.getattr("_variant")?.extract::<String>()?.as_str() {
        "unspecified" => Ok(zipzi_core::SceneReference::Unspecified),
        "resolved" => Ok(zipzi_core::SceneReference::Resolved {
            object_id: value.getattr("object_id")?.extract()?,
        }),
        "unresolved" => Ok(zipzi_core::SceneReference::Unresolved {
            runtime_id: value.getattr("runtime_id")?.extract()?,
        }),
        _ => Err(pyo3::exceptions::PyTypeError::new_err(
            "Unexpected modeling variant",
        )),
    }
}

